+/**
+ * 根据紫外线指数（UV Index）返回对应的防护建议。
+ *
+ * 分级：0-2 弱、3-5 中等、6-7 强、8 及以上 极强。
+ * 非法输入（非数值、非有限数值或负数）返回 null。
+ *
+ * @param {number} uv 紫外线指数
+ * @returns {'弱' | '中等' | '强' | '极强' | null}
+ */
+export function uvAdvice(uv) {
+  if (typeof uv !== 'number' || !Number.isFinite(uv) || uv < 0) {
+    return null;
+  }
+  if (uv <= 2) return '弱';
+  if (uv <= 5) return '中等';
+  if (uv <= 7) return '强';
+  return '极强';
+}
